445:   public void onStart() {
446:     Log.d(LOG_TAG, "onStart is called.");
447:     Trace.beginSection("AndroidJUnitRunner#onStart");
448:     Bundle results = new Bundle();
449:     try {
450:       setJsBridgeClassName("androidx.test.espresso.web.bridge.JavaScriptBridge");
451:       super.onStart();
452: 
453:       Request testRequest = buildRequest(runnerArgs, getArguments());
454: 
455:       if (runnerArgs.remoteMethod != null) {
456:         invokeRemoteMethod();
457:       }
458: 
459:       // TODO(b/162075422): using deprecated isPrimaryInstrProcess(argsProcessName) method
460:       if (!isPrimaryInstrProcess(runnerArgs.targetProcess)) {
461:         Log.i(LOG_TAG, "Runner is idle...");
462:         return;
463:       }
464: 
465:       TestExecutor.Builder executorBuilder = new TestExecutor.Builder(this);
466:       addListeners(runnerArgs, executorBuilder);
467:       results = executorBuilder.build().execute(testRequest);
468:     } catch (Throwable t) {
469:       final String msg = "Fatal exception when running tests";
470:       Log.e(LOG_TAG, msg, t);
471:       onException(this, t);
472:     } finally {
473:       Trace.endSection();
474:     }
475:     // finish kills the process, so this needs to happen after Trace.endSection
476:     finish(Activity.RESULT_OK, results);
477:   }

599:   public boolean onException(Object obj, Throwable e) {
600:     Throwable cause = unwrapException(e);
601:     if (appExceptionsHandled.contains(cause)) {
602:       Log.d(
603:           LOG_TAG,
604:           String.format(
605:               "We've already handled this exception %s. Ignoring.", cause.getClass().getName()));
606:       return false;
607:     }
608: 
609:     Log.w(LOG_TAG, "An unhandled exception was thrown by the app.", e);
610:     appExceptionsHandled.add(cause);
611: 
612:     // Report better error message back to Instrumentation results.
613:     InstrumentationResultPrinter instResultPrinter = getInstrumentationResultPrinter();
614:     // If the app crashes before instrumentation has started, instrumentationResultPrinter could
615:     // be null
616:     if (instResultPrinter != null) {
617:       if (instResultPrinter.getInstrumentation() == null) {
618:         // App could crash before #onCreate(Bundle) is called, where the instrumentation instance is
619:         // not properly set yet. Setting the Instrumentation here rather than in the constructor to
620:         // minimize the dependencies during initialization.
621:         instResultPrinter.setInstrumentation(this);
622:       }
623: 
624:       // Allows DISK_WRITE as `sendStatus` writes to standard output.
625:       final StrictMode.ThreadPolicy oldPolicy = StrictMode.allowThreadDiskWrites();
626:       try {
627:         instResultPrinter.reportProcessCrash(e);
628:       } catch (Throwable t) {
629:         // It is possible for the test infrastructure to get sufficiently messed up that even this
630:         // can fail (with a NoSuchMethodError from Failure.getTrace()!). Don't let that get in the
631:         // way of sending events reporting the problems, since that can make the difference between
632:         // "test failed with a useful error message" and "test mysteriously timed out and the
633:         // developer has to go spelunking in the system logcat".
634:         Log.e(LOG_TAG, "Failed to report process crash.", t);
635:       } finally {
636:         StrictMode.setThreadPolicy(oldPolicy);
637:       }
638:     }

391:   public void finish(int resultCode, Bundle results) {
392:     if (finished) {
393:       Log.w(TAG, "finish called 2x!");
394:       return;
395:     } else {
396:       finished = true;
397:     }
398: 
399:     Trace.beginSection("MonitoringInstrumentation#finish");
400:     if (shouldWaitForActivitiesToComplete()) {
401:       handlerForMainLooper.post(new ActivityFinisher());
402:       waitForActivitiesToComplete();
403:     }
404:     ActivityLifecycleMonitorRegistry.registerInstance(null);
405:     restoreUncaughtExceptionHandler();
406:     Trace.endSection();
407: 
408:     // super.finish kills the current process, so this needs to be called last
409:     super.finish(resultCode, results);
410:   }
