412:   protected boolean shouldWaitForActivitiesToComplete() {
413:     // TODO(b/72831103): default this argument to false in a future release
414:     return Boolean.parseBoolean(
415:         InstrumentationRegistry.getArguments().getString("waitForActivitiesToComplete", "true"));
416:   }
