418:   /**
419:    * Ensures we've onStopped() all activities which were onStarted().
420:    *
421:    * <p>According to Activity's contract, the process is not killable between onStart and onStop.
422:    * Breaking this contract (which finish() will if you let it) can cause bad behaviour (including a
423:    * full restart of system_server).
424:    *
425:    * <p>We give the app 2 seconds to stop all its activities, then we proceed.
426:    *
427:    * <p>This should never be run on the main thread.
428:    */
429:   protected void waitForActivitiesToComplete() {
430:     if (Looper.getMainLooper() == Looper.myLooper()) {
431:       throw new IllegalStateException("Cannot be called from main thread!");
432:     }
433: 
434:     long endTime = System.currentTimeMillis() + MILLIS_TO_WAIT_FOR_ACTIVITY_TO_STOP;
435:     int currentActivityCount = startedActivityCounter.get();
436:     while (currentActivityCount > 0 && System.currentTimeMillis() < endTime) {
437:       try {
438:         Log.i(TAG, "Unstopped activity count: " + currentActivityCount);
439:         Thread.sleep(MILLIS_TO_POLL_FOR_ACTIVITY_STOP);
440:         currentActivityCount = startedActivityCounter.get();
441:       } catch (InterruptedException ie) {
442:         Log.i(TAG, "Abandoning activity wait due to interruption.", ie);
443:         break;
444:       }
445:     }
446: 
447:     if (currentActivityCount > 0) {
448:       dumpThreadStateToOutputs("ThreadState-unstopped.txt");
449:       Log.w(
450:           TAG,
451:           String.format(
452:               "Still %s activities active after waiting %s ms.",
453:               currentActivityCount, MILLIS_TO_WAIT_FOR_ACTIVITY_TO_STOP));

